import type {
  GoogleSheetRow,
  IGoogleSheetsService,
} from "@/externals/google/sheet/types";
import { DETAIL_HEADERS, ensureHeader, MASTER_HEADERS } from "./state";
import { isValidMovementQuantity, parseQuantity } from "@/features/backend/line/services/movements/utils";

export class MovementQuantityRequiredError extends Error {
  constructor() {
    super("Set a quantity greater than 0 for every item before marking delivered.");
    this.name = "MovementQuantityRequiredError";
  }
}

export type MovementStatus = "in_progress" | "created" | "delivered";

export type ProductMovementRecord = {
  movementId: string;
  movementMasterId: string;
  shopName: string;
  quantity: string;
  remark: string;
  fromLocation: string;
  toLocation: string;
  productImageUrl: string;
  purchaseDetailId: string;
  status: "created" | "delivered";
  createdAt: string;
  updatedAt: string;
  stockCounted: boolean;
  isNewArrival: boolean;
};

export type ProductMovementMasterRecord = {
  id: string;
  userId: string;
  packingDate: string;
  deliverDateTime?: string;
  status: MovementStatus;
  totalQuantity: string;
  createdAt: string;
  updatedAt: string;
  itemCount: number;
  shopQuantities: Record<string, number>;
};

export type MovementDateFilter = {
  date?: string;
  fromDate?: string;
  toDate?: string;
};

export async function listMovements({
  filter,
  googleSheetsService,
}: {
  filter: MovementDateFilter;
  googleSheetsService: IGoogleSheetsService;
}): Promise<ProductMovementMasterRecord[]> {
  await Promise.all([
    ensureHeader(googleSheetsService.movementMasters, MASTER_HEADERS, "H"),
    ensureHeader(googleSheetsService.movementDetails, DETAIL_HEADERS, "N"),
  ]);
  const [masterRows, detailRows] = await Promise.all([
    googleSheetsService.movementMasters.readRows("A2:H"),
    googleSheetsService.movementDetails.readRows("A2:N"),
  ]);
  const detailsByMaster = new Map<string, ProductMovementRecord[]>();
  for (const row of detailRows) {
    const detail = rowToMovement(row);
    if (!detail.movementId || !detail.movementMasterId) continue;
    detailsByMaster.set(detail.movementMasterId, [
      ...(detailsByMaster.get(detail.movementMasterId) || []),
      detail,
    ]);
  }

  return masterRows
    .map((row) =>
      rowToMovementMaster(row, detailsByMaster.get(cell(row[0])) || []),
    )
    .filter((record) => record.id && matchesDateFilter(record, filter));
}

export async function getMovementItems({
  googleSheetsService,
  movementMasterId,
}: {
  googleSheetsService: IGoogleSheetsService;
  movementMasterId: string;
}): Promise<ProductMovementRecord[]> {
  await ensureHeader(googleSheetsService.movementDetails, DETAIL_HEADERS, "N");
  const normalizedId = movementMasterId.toUpperCase();
  return (await googleSheetsService.movementDetails.readRows("A2:N"))
    .map(rowToMovement)
    .filter(
      (record) =>
        record.movementId &&
        record.movementMasterId.toUpperCase() === normalizedId,
    );
}

export async function movementExists({
  googleSheetsService,
  movementMasterId,
}: {
  googleSheetsService: IGoogleSheetsService;
  movementMasterId: string;
}): Promise<boolean> {
  const rows = await googleSheetsService.movementMasters.readRows("A2:A");
  return rows.some((row) => cell(row[0]).toUpperCase() === movementMasterId.toUpperCase());
}

export async function deleteMovementItem({
  googleSheetsService,
  movementId,
  movementMasterId,
}: {
  googleSheetsService: IGoogleSheetsService;
  movementId: string;
  movementMasterId: string;
}): Promise<ProductMovementRecord[]> {
  await ensureHeader(googleSheetsService.movementDetails, DETAIL_HEADERS, "N");
  const rows = await googleSheetsService.movementDetails.readRows("A:N");
  const rowIndex = rows.findIndex((row, index) => index > 0 &&
    cell(row[0]).toUpperCase() === movementId.toUpperCase() &&
    cell(row[1]).toUpperCase() === movementMasterId.toUpperCase(),
  );
  if (rowIndex !== -1) {
    const sheet = googleSheetsService.movementDetails;
    if (!sheet.deleteRow) throw new Error("Movement row deletion is unavailable.");
    // Delete the entire Sheets row, not only its image link or cell contents.
    // The separate Drive file remains untouched.
    await sheet.deleteRow(rowIndex + 1);
  }
  // Recompute even on retries: a previous row deletion may have succeeded before a
  // failed total update or HTTP response.
  await refreshMovementMaster(googleSheetsService, movementMasterId);
  return getMovementItems({ googleSheetsService, movementMasterId });
}

export async function updateMovementItem({
  googleSheetsService,
  movementId,
  movementMasterId,
  quantity,
  remark,
  stockCounted,
  isNewArrival,
}: {
  googleSheetsService: IGoogleSheetsService;
  movementId: string;
  movementMasterId: string;
  quantity?: string;
  remark?: string;
  stockCounted?: boolean;
  isNewArrival?: boolean;
}): Promise<ProductMovementRecord[] | null> {
  await ensureHeader(googleSheetsService.movementDetails, DETAIL_HEADERS, "N");
  const rows = await googleSheetsService.movementDetails.readRows("A:N");
  const rowIndex = rows.findIndex(
    (row, index) =>
      index > 0 &&
      cell(row[0]).toUpperCase() === movementId.toUpperCase() &&
      cell(row[1]).toUpperCase() === movementMasterId.toUpperCase(),
  );
  if (rowIndex === -1) return null;

  const nextRow = [...rows[rowIndex]];
  while (nextRow.length < DETAIL_HEADERS.length) nextRow.push("");
  if (quantity !== undefined) nextRow[3] = quantity;
  if (remark !== undefined) {
    nextRow[4] = remark;
    if (remark !== cell(rows[rowIndex][4])) {
      const calculated = parseQuantity(remark);
      if (calculated) nextRow[3] = calculated.quantity;
    }
  }
  if (stockCounted !== undefined) nextRow[12] = stockCounted;
  if (isNewArrival !== undefined) nextRow[13] = isNewArrival;
  nextRow[11] = new Date().toISOString();
  await googleSheetsService.movementDetails.updateRows(
    `A${rowIndex + 1}:N${rowIndex + 1}`,
    [nextRow],
  );
  await refreshMovementMaster(googleSheetsService, movementMasterId);
  return getMovementItems({ googleSheetsService, movementMasterId });
}

export async function updateMovementImage({
  googleSheetsService,
  imageUrl,
  movementId,
  movementMasterId,
}: {
  googleSheetsService: IGoogleSheetsService;
  imageUrl: string;
  movementId: string;
  movementMasterId: string;
}): Promise<ProductMovementRecord[] | null> {
  await ensureHeader(googleSheetsService.movementDetails, DETAIL_HEADERS, "N");
  const rows = await googleSheetsService.movementDetails.readRows("A:N");
  const rowIndex = rows.findIndex(
    (row, index) =>
      index > 0 &&
      cell(row[0]).toUpperCase() === movementId.toUpperCase() &&
      cell(row[1]).toUpperCase() === movementMasterId.toUpperCase(),
  );
  if (rowIndex === -1) return null;

  const nextRow = [...rows[rowIndex]];
  while (nextRow.length < DETAIL_HEADERS.length) nextRow.push("");
  nextRow[7] = imageUrl;
  nextRow[11] = new Date().toISOString();
  await googleSheetsService.movementDetails.updateRows(
    `A${rowIndex + 1}:N${rowIndex + 1}`,
